-- マイ個人 — RESTAURAÇÃO TOTAL DE DADOS E CONTA RESGATADOS
-- Execute este script no SQL Editor do Supabase Dashboard
-- ============================================================

CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- 1. Garante colunas necessárias em perfil_usuario
ALTER TABLE public.perfil_usuario ADD COLUMN IF NOT EXISTS tipo_perfil TEXT DEFAULT 'individual';
ALTER TABLE public.perfil_usuario ADD COLUMN IF NOT EXISTS nome_empresa TEXT;
ALTER TABLE public.perfil_usuario ADD COLUMN IF NOT EXISTS telefone_corporativo TEXT;

DO $$
DECLARE
  v_manager_id UUID := '9e3119e8-a0f9-4536-af47-c09d37553c53';
  v_email TEXT := 'ruyhayashihara@gmail.com';
  v_name TEXT := 'Ruy Hayashihara';
  v_password TEXT := 'MudeSuaSenha123!';
  v_existing_id UUID;
BEGIN
  -- Se existir conta com mesmo e-mail mas UUID diferente, remove para restaurar UUID original
  SELECT id INTO v_existing_id FROM auth.users WHERE email = v_email;
  IF v_existing_id IS NOT NULL AND v_existing_id != v_manager_id THEN
    DELETE FROM public.perfil_usuario WHERE id = v_existing_id;
    DELETE FROM auth.users WHERE id = v_existing_id;
  END IF;

  -- 2. Restaura o usuário em auth.users
  IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id = v_manager_id) THEN
    INSERT INTO auth.users (
      instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
      raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
      confirmation_token, recovery_token, email_change_token_new, email_change
    ) VALUES (
      '00000000-0000-0000-0000-000000000000', v_manager_id, 'authenticated', 'authenticated',
      v_email, crypt(v_password, gen_salt('bf')), NOW(),
      '{"provider":"email","providers":["email"]}'::jsonb,
      jsonb_build_object('nome', v_name, 'tipo_perfil', 'gestor'),
      '2026-03-30 12:20:23+00'::timestamptz, NOW(), '', '', '', ''
    );
    RAISE NOTICE 'Conta de autenticação restaurada: % (ID: %)', v_email, v_manager_id;
  ELSE
    UPDATE auth.users SET
      encrypted_password = crypt(v_password, gen_salt('bf')),
      email_confirmed_at = NOW(),
      raw_user_meta_data = jsonb_build_object('nome', v_name, 'tipo_perfil', 'gestor'),
      updated_at = NOW()
    WHERE id = v_manager_id;
    RAISE NOTICE 'Conta de autenticação atualizada: % (ID: %)', v_email, v_manager_id;
  END IF;

  -- 3. Restaura o perfil do gestor
  INSERT INTO public.perfil_usuario (id, nome, tipo_perfil, moeda, ano_fiscal_atual)
  VALUES (v_manager_id, v_name, 'gestor', '¥', EXTRACT(YEAR FROM NOW()))
  ON CONFLICT (id) DO UPDATE SET
    tipo_perfil = 'gestor',
    nome = v_name;

  RAISE NOTICE 'Perfil de gestor configurado com sucesso.';
END $$;

